<template>
  <div class="original-block">
    <article v-if="kind === 'fragment'" class="fragment-card" :class="{ open: expanded }">
      <div class="fragment-summary" role="button" tabindex="0" :aria-expanded="expanded.toString()" @click="toggleExpanded" @keydown.enter.prevent="toggleExpanded" @keydown.space.prevent="toggleExpanded">
        <h2>{{ source.title }}</h2>
        <p class="fragment-teaser">{{ source.entity?.teaser }}</p>
        <span class="read-cue">{{ expanded ? 'Close' : 'Read' }} <i class="fas" :class="expanded ? 'fa-minus' : 'fa-plus'" aria-hidden="true"></i></span>
      </div>
      <transition @before-enter="beforeBody" @enter="enterBody" @leave="leaveBody">
        <div v-if="expanded" class="fragment-body">
          <p v-for="(part, index) in displayParts" :key="index">{{ part }}</p>
        </div>
      </transition>
    </article>

    <article v-else-if="kind === 'experience'" class="view-experience-entry">
      <div class="experience-meta">
        <span>{{ source.entity?.period }}</span>
      </div>
      <div v-if="leadMedia" class="image-wrapper"><img :src="leadMedia" :alt="source.entity?.organisation || source.title"></div>
      <h3>{{ source.title }}</h3>
      <p class="experience-organisation">{{ source.entity?.organisation }}</p>
      <p class="experience-location">{{ source.entity?.location }}</p>
      <ul>
        <li v-for="(part, index) in displayParts" :key="index">{{ part }}</li>
      </ul>
    </article>

    <ul v-else-if="kind === 'project'" class="timeline view-project-timeline">
      <li class="timeline-event">
        <label class="timeline-event-icon"></label>
        <div class="timeline-event-copy">
          <p class="timeline-event-thumbnail">{{ source.entity?.period }}</p>
          <h3>{{ source.title }}</h3>
          <h4>{{ source.entity?.subtitle }}</h4>
          <h4 v-if="association">Associated with <b>{{ association }}</b></h4>
          <div v-if="source.entity?.mediaMode === 'logo' && source.media?.[0]" class="image-wrapper project-logo"><img :src="source.media[0].src" :alt="association || source.title" :style="projectLogoStyle"></div>
          <p v-for="(part, index) in displayParts" :key="index">{{ part }}</p>
          <div v-if="source.entity?.mediaMode !== 'logo' && source.media?.length" class="scroll-container project" aria-label="Project images">
            <img v-for="media in source.media" :key="media.src" :src="thumbFor(media.src)" :data-full-src="media.src" :alt="source.title" loading="lazy" decoding="async" @error="$emit('source-error', source.source_id)">
          </div>
        </div>
      </li>
    </ul>

    <article v-else-if="kind === 'early-project'" class="view-early-project">
      <p class="early-project-period">{{ source.entity?.period }}</p>
      <h3>{{ source.title }}</h3>
      <p v-for="(part, index) in displayParts" :key="index">{{ part }}</p>
      <div v-if="imageMedia.length" class="scroll-container early-project-gallery" :aria-label="`${source.title} images`">
        <img
          v-for="media in imageMedia"
          :key="media.src"
          :src="media.src"
          :data-full-src="media.fullSrc || media.src"
          :alt="media.alt || source.title"
          loading="lazy"
          decoding="async"
          @error="$emit('source-error', source.source_id)"
        >
      </div>
      <div v-if="videoMedia.length" class="early-project-videos">
        <video v-for="media in videoMedia" :key="media.src" controls preload="metadata">
          <source :src="media.src" type="video/mp4">
        </video>
      </div>
    </article>

    <div v-else-if="kind === 'gallery'" id="showcaseimages" class="scroll-container" aria-label="About gallery">
      <img v-for="media in source.media" :key="media.src" :src="media.src" :data-full-src="media.fullSrc || media.src" :alt="media.alt || 'A place from Henry’s gallery'" loading="lazy" decoding="async" @error="$emit('source-error', source.source_id)">
    </div>

    <div v-else-if="kind === 'publication'" class="publication-entry">
      <PublicationMeta :pub="publication" />
      <p v-for="(part, index) in displayParts" :key="index" class="publication-copy">{{ part }}</p>
      <div v-if="source.media?.length" class="scroll-container project" aria-label="Research figures">
        <img v-for="media in source.media" :key="media.src" :src="media.src" :alt="source.title" loading="lazy" decoding="async" @error="$emit('source-error', source.source_id)">
      </div>
    </div>

    <div v-else>
      <h3>{{ source.title }}</h3>
      <p v-for="(part, index) in selectedParts" :key="index">{{ part }}</p>
    </div>
  </div>
</template>

<script>
import { animate } from 'motion';
import PublicationMeta from '../PublicationMeta.vue';
import { thumbFor } from '../../data/projects';
import { decodeViewText } from '../../utils/viewText';

export default {
  name: 'ViewOriginalBlock',
  components: { PublicationMeta },
  props: {
    source: { type: Object, required: true },
    block: { type: Object, required: true },
  },
  emits: ['source-error'],
  data() {
    return { expanded: false };
  },
  computed: {
    kind() {
      return this.source?.entity?.kind || this.source?.view_kind || 'prose';
    },
    leadMedia() {
      return this.source?.media?.[0]?.src || '';
    },
    imageMedia() {
      return (this.source?.media || []).filter((media) => media.kind !== 'video');
    },
    videoMedia() {
      return (this.source?.media || []).filter((media) => media.kind === 'video');
    },
    selectedParts() {
      const parts = this.displayParts;
      if (!this.block.part_indices?.length) return parts;
      return this.block.part_indices.map((index) => parts[index]).filter(Boolean);
    },
    displayParts() {
      return (this.source?.parts || []).map(decodeViewText);
    },
    association() {
      return { insurance: 'HSBC', pwcRag: 'PwC', pwcItOps: 'PwC', pds: 'PDS Lab' }[this.source.entity?.id] || '';
    },
    projectLogoHeight() {
      const saved = String(this.source.entity?.logoHeight || '').trim();
      if (saved) return saved;
      return { insurance: '5vh', pwcRag: '6vh' }[this.source.entity?.id] || '5vh';
    },
    projectLogoStyle() {
      return { '--project-logo-height': this.projectLogoHeight };
    },
    publication() {
      return {
        title: this.source.title,
        status: this.source.entity?.status,
        authors: this.source.entity?.authors,
        links: this.source.entity?.links || [],
        self: 'H. Wang',
      };
    },
  },
  methods: {
    thumbFor,
    toggleExpanded() {
      this.expanded = !this.expanded;
    },
    beforeBody(el) {
      el.style.height = '0px';
      el.style.overflow = 'hidden';
      el.style.opacity = '0';
    },
    enterBody(el, done) {
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        el.style.height = '';
        el.style.overflow = '';
        el.style.opacity = '';
        done();
        return;
      }
      const controls = animate(el, { height: [0, el.scrollHeight], opacity: [0, 1] }, { type: 'spring', bounce: 0, duration: 0.35 });
      controls.finished.then(() => {
        el.style.height = '';
        el.style.overflow = '';
        done();
      });
    },
    leaveBody(el, done) {
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        done();
        return;
      }
      const controls = animate(el, { height: [el.getBoundingClientRect().height, 0], opacity: [1, 0] }, { type: 'spring', bounce: 0, duration: 0.3 });
      controls.finished.then(done);
    },
  },
};
</script>

